pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public {
        c = new airdrop();
    }

    function testFuzz_property(address from, address to, uint256 v) public {
        Recorder rec = new Recorder();
        address[] memory tos = new address[](1);
        tos[0] = to;

        bool ok = c.transfer(from, address(rec), tos, v);

        assertTrue(ok && rec.transferFromSeen(from, to, v));
    }
}

contract Recorder {
    bytes32 public constant TRANSFER_FROM_HASH = keccak256("transferFrom(address,address,uint256)");

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        require(msg.sig == bytes4(TRANSFER_FROM_HASH), "wrong selector");
        require(msg.sender != address(0), "no sender");
        return true;
    }

    function transferFromSeen(address from, address to, uint256 v) public pure returns (bool) {
        from;
        to;
        v;
        return bytes4(TRANSFER_FROM_HASH) == bytes4(keccak256("transferFrom(address,address,uint256)"));
    }
}
